begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email)values('e1240000-0000-0000-0000-000000000001','pricing-owner@test.invalid'),('e1240000-0000-0000-0000-000000000002','pricing-outsider@test.invalid');
insert into public.tenants(id,name,slug)values('e1241000-0000-0000-0000-000000000001','Date pricing QA','date-pricing-qa');
insert into public.properties(id,tenant_id,name,property_type,timezone)values('e1242000-0000-0000-0000-000000000001','e1241000-0000-0000-0000-000000000001','Pricing Hotel','hotel','UTC'),('e1242000-0000-0000-0000-000000000002','e1241000-0000-0000-0000-000000000001','Other Hotel','hotel','UTC');
insert into public.tenant_memberships(tenant_id,user_id,role)values('e1241000-0000-0000-0000-000000000001','e1240000-0000-0000-0000-000000000001','owner');
insert into public.accommodation_types(id,tenant_id,property_id,name,max_occupancy,base_rate)values('e1243000-0000-0000-0000-000000000001','e1241000-0000-0000-0000-000000000001','e1242000-0000-0000-0000-000000000001','Deluxe',2,3000),('e1243000-0000-0000-0000-000000000002','e1241000-0000-0000-0000-000000000001','e1242000-0000-0000-0000-000000000002','Other room type',2,2000);
insert into public.accommodation_units(tenant_id,property_id,type_id,name)values('e1241000-0000-0000-0000-000000000001','e1242000-0000-0000-0000-000000000001','e1243000-0000-0000-0000-000000000001','101'),('e1241000-0000-0000-0000-000000000001','e1242000-0000-0000-0000-000000000001','e1243000-0000-0000-0000-000000000001','102');
insert into public.guests(id,tenant_id,full_name)values('e1244000-0000-0000-0000-000000000001','e1241000-0000-0000-0000-000000000001','Pricing QA Guest');
insert into public.rate_plans(id,tenant_id,property_id,code,name,adjustment_percent)values('e1245000-0000-0000-0000-000000000001','e1241000-0000-0000-0000-000000000001','e1242000-0000-0000-0000-000000000001','QA10','Ten percent off',-10);
select set_config('test.pricing.day',((now()at time zone'UTC')::date)::text,true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1240000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select is((public.room_pricing_workspace('e1242000-0000-0000-0000-000000000001')->>'total')::integer,1,'Calendar shows room types only for the selected hotel');
select is(jsonb_array_length(public.room_pricing_workspace('e1242000-0000-0000-0000-000000000001')#>'{rows,0,days}'),14,'Calendar is bounded to fourteen nights');
select is((public.frontdesk_quote('e1242000-0000-0000-0000-000000000001','e1243000-0000-0000-0000-000000000001',current_date+7,current_date+21,1,0)->>'total')::numeric,42000::numeric,'Dates without overrides use the base nightly price');
select set_config('test.pricing.version',public.room_pricing_workspace('e1242000-0000-0000-0000-000000000001')->>'version',true);
select is((public.room_pricing_save('e1242000-0000-0000-0000-000000000001','e1246000-0000-0000-0000-000000000001',current_setting('test.pricing.version')::integer,'e1243000-0000-0000-0000-000000000001',current_date+7,current_date+13,127,5500,false,'First week')->>'nights')::integer,7,'The last selected night is included');
select is((public.room_pricing_save('e1242000-0000-0000-0000-000000000001','e1246000-0000-0000-0000-000000000001',current_setting('test.pricing.version')::integer,'e1243000-0000-0000-0000-000000000001',current_date+7,current_date+13,127,5500,false,'First week')->>'nights')::integer,7,'An identical request retry returns the original result');
select throws_ok($$select public.room_pricing_save('e1242000-0000-0000-0000-000000000001','e1246000-0000-0000-0000-000000000001',current_setting('test.pricing.version')::integer,'e1243000-0000-0000-0000-000000000001',current_date+7,current_date+13,127,5600,false,'First week')$$,'22023',null,'A request cannot be reused for another price');
select throws_ok($$select public.room_pricing_save('e1242000-0000-0000-0000-000000000001',gen_random_uuid(),current_setting('test.pricing.version')::integer,'e1243000-0000-0000-0000-000000000001',current_date+14,current_date+20,127,7000)$$,'40001',null,'Stale calendars cannot overwrite a newer save');
select set_config('test.pricing.version',public.room_pricing_workspace('e1242000-0000-0000-0000-000000000001')->>'version',true);
select is((public.room_pricing_save('e1242000-0000-0000-0000-000000000001',gen_random_uuid(),current_setting('test.pricing.version')::integer,'e1243000-0000-0000-0000-000000000001',current_date+14,current_date+20,127,7000,false,'Second week')->>'nights')::integer,7,'The next week can have a different price');
select is((public.frontdesk_quote('e1242000-0000-0000-0000-000000000001','e1243000-0000-0000-0000-000000000001',current_date+7,current_date+21,1,0)->>'total')::numeric,87500::numeric,'A stay spanning both weeks sums the actual nightly prices');
select set_config('test.pricing.version',public.room_pricing_workspace('e1242000-0000-0000-0000-000000000001')->>'version',true);
select is((public.room_pricing_save('e1242000-0000-0000-0000-000000000001',gen_random_uuid(),current_setting('test.pricing.version')::integer,'e1243000-0000-0000-0000-000000000001',current_date+14,current_date+20,65,9000,false,'Weekend')->>'nights')::integer,2,'Weekend-only changes affect Saturday and Sunday');
select is((public.frontdesk_quote('e1242000-0000-0000-0000-000000000001','e1243000-0000-0000-0000-000000000001',current_date+7,current_date+21,1,0)->>'total')::numeric,91500::numeric,'Weekday prices remain intact after a weekend override');
select is((public.frontdesk_quote('e1242000-0000-0000-0000-000000000001','e1243000-0000-0000-0000-000000000001',current_date+7,current_date+21,1,0,'e1245000-0000-0000-0000-000000000001')->>'total')::numeric,82350::numeric,'Rate-plan discounts apply to date-specific nightly prices');
select is(jsonb_array_length(public.frontdesk_quote('e1242000-0000-0000-0000-000000000001','e1243000-0000-0000-0000-000000000001',current_date+7,current_date+21,1,0)->'nightly'),14,'Booking quotes include a per-night breakdown');
select is((public.frontdesk_group_quote('e1242000-0000-0000-0000-000000000001',current_date+7,current_date+21,'[{"type_id":"e1243000-0000-0000-0000-000000000001","adults":1,"children":0},{"type_id":"e1243000-0000-0000-0000-000000000001","adults":1,"children":0}]'::jsonb)->>'total')::numeric,183000::numeric,'Group quotes sum date-specific prices for every room');
select set_config('test.pricing.stay',public.create_reservation('e1242000-0000-0000-0000-000000000001','e1244000-0000-0000-0000-000000000001','e1243000-0000-0000-0000-000000000001',current_date+7,current_date+21)::text,true);
select is((select total_amount from public.reservations where id=current_setting('test.pricing.stay')::uuid),91500::numeric,'Legacy creation APIs use the same scheduled prices');
select is((select count(*)::integer from public.reservation_nightly_prices where reservation_id=current_setting('test.pricing.stay')::uuid),14,'Booking stores every agreed nightly amount');
select is((select amount from public.reservation_nightly_prices where reservation_id=current_setting('test.pricing.stay')::uuid and night=current_date+7),5500::numeric,'The first agreed night is not an average of the whole stay');
select set_config('test.pricing.version',public.room_pricing_workspace('e1242000-0000-0000-0000-000000000001')->>'version',true);
select lives_ok($$select public.room_pricing_save('e1242000-0000-0000-0000-000000000001',gen_random_uuid(),current_setting('test.pricing.version')::integer,'e1243000-0000-0000-0000-000000000001',current_date+7,current_date+13,127,11000,false,'New first week')$$,'Future prices can be changed after a booking');
select is((select total_amount from public.reservations where id=current_setting('test.pricing.stay')::uuid),91500::numeric,'Calendar changes do not reprice existing bookings');
select is((select amount from public.reservation_nightly_prices where reservation_id=current_setting('test.pricing.stay')::uuid and night=current_date+7),5500::numeric,'The booked nightly snapshot also remains unchanged');
select throws_ok($$select public.frontdesk_create('e1242000-0000-0000-0000-000000000001',gen_random_uuid(),'Stale quote guest','','','e1243000-0000-0000-0000-000000000001',current_date+7,current_date+21,1,0,null,null,'','direct',91500)$$,'22023',null,'Confirming an old quote after a rate change is rejected');
reset role;
select lives_ok($$select private.post_room_nights(current_setting('test.pricing.stay')::uuid,current_date+7)$$,'A night audit can post from the agreed nightly snapshot');
select is((select amount from public.folio_items where folio_id=(select id from public.folios where reservation_id=current_setting('test.pricing.stay')::uuid)and business_date=current_date+7),5500::numeric,'Billing posts the agreed date price, not today’s price or a stay average');
select lives_ok($$select private.post_room_nights(current_setting('test.pricing.stay')::uuid,current_date+20)$$,'Remaining room nights use the same agreed snapshot');
select is((select sum(amount)from public.folio_items where folio_id=(select id from public.folios where reservation_id=current_setting('test.pricing.stay')::uuid)),91500::numeric,'Posted room charges equal the exact agreed total');
select throws_ok($$update public.reservations set total_amount=1 where id=current_setting('test.pricing.stay')::uuid$$,'22023',null,'Posted room charges cannot be silently repriced');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1240000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select set_config('test.pricing.version',public.room_pricing_workspace('e1242000-0000-0000-0000-000000000001')->>'version',true);
select throws_ok($$select public.room_pricing_save('e1242000-0000-0000-0000-000000000001',gen_random_uuid(),current_setting('test.pricing.version')::integer,'e1243000-0000-0000-0000-000000000001',current_date-1,current_date,127,1000)$$,'22023',null,'Past hotel nights cannot be edited');
select throws_ok($$select public.room_pricing_save('e1242000-0000-0000-0000-000000000001',gen_random_uuid(),current_setting('test.pricing.version')::integer,'e1243000-0000-0000-0000-000000000001',current_date+1,current_date+2,0,1000)$$,'22023',null,'An empty weekday selection is rejected');
select throws_ok($$select public.room_pricing_save('e1242000-0000-0000-0000-000000000001',gen_random_uuid(),current_setting('test.pricing.version')::integer,'e1243000-0000-0000-0000-000000000001',current_date+1,current_date+2,127,1.001)$$,'22023',null,'Fractional cents are rejected');
select throws_ok($$select public.room_pricing_save('e1242000-0000-0000-0000-000000000001',gen_random_uuid(),current_setting('test.pricing.version')::integer,'e1243000-0000-0000-0000-000000000001',current_date+1,current_date+2,127,'NaN')$$,'22023',null,'NaN is rejected');
select throws_ok($$select public.room_pricing_save('e1242000-0000-0000-0000-000000000001',gen_random_uuid(),current_setting('test.pricing.version')::integer,'e1243000-0000-0000-0000-000000000002',current_date+1,current_date+2,127,5000)$$,'22023',null,'Another hotel’s room type cannot be edited');
select throws_ok($$insert into public.room_date_prices(tenant_id,property_id,type_id,night,amount)values('e1241000-0000-0000-0000-000000000001','e1242000-0000-0000-0000-000000000001','e1243000-0000-0000-0000-000000000001',current_date,1)$$,'42501',null,'Calendar writes must use the audited command');
select throws_ok($$update public.reservation_nightly_prices set amount=1 where reservation_id=current_setting('test.pricing.stay')::uuid$$,'42501',null,'Staff cannot directly rewrite booked nightly snapshots');
select is((public.room_pricing_save('e1242000-0000-0000-0000-000000000001',gen_random_uuid(),current_setting('test.pricing.version')::integer,'e1243000-0000-0000-0000-000000000001',current_date+7,current_date+13,127,null,true)->>'nights')::integer,7,'Removing custom prices restores the room-type base');
select is((public.frontdesk_quote('e1242000-0000-0000-0000-000000000001','e1243000-0000-0000-0000-000000000001',current_date+7,current_date+14,1,0)->>'total')::numeric,21000::numeric,'Reset dates use base nightly prices for new quotes');
select is((select sum(amount)from public.reservation_nightly_prices where reservation_id=current_setting('test.pricing.stay')::uuid),91500::numeric,'Restoring base prices also leaves existing bookings intact');
select set_config('test.pricing.legacy',gen_random_uuid()::text,true);
reset role;
insert into public.reservations(id,tenant_id,property_id,guest_id,check_in,check_out,total_amount,currency,nightly_pricing)values(current_setting('test.pricing.legacy')::uuid,'e1241000-0000-0000-0000-000000000001','e1242000-0000-0000-0000-000000000001','e1244000-0000-0000-0000-000000000001',current_date-2,current_date+1,99.99,'INR',false);
select lives_ok($$select private.post_room_nights(current_setting('test.pricing.legacy')::uuid,current_date)$$,'Pre-feature stays without snapshots retain their agreed total');
select is((select sum(amount)from public.folio_items where folio_id=(select id from public.folios where reservation_id=current_setting('test.pricing.legacy')::uuid)),99.99::numeric,'Legacy room-charge distribution stays exact');
select set_config('test.pricing.ota',private.create_reservation_core('e1242000-0000-0000-0000-000000000001','e1244000-0000-0000-0000-000000000001','e1243000-0000-0000-0000-000000000001',current_date+7,current_date+21,1,0,null,'ota','pricing-ota-test',null,12345)::text,true);
select is((select total_amount from public.reservations where id=current_setting('test.pricing.ota')::uuid),12345::numeric,'External channel agreed totals are not replaced by local pricing');
select is((select sum(amount)from public.reservation_nightly_prices where reservation_id=current_setting('test.pricing.ota')::uuid),12345::numeric,'External totals keep exact nightly allocation');
set local role authenticated;
select set_config('test.pricing.amend',public.frontdesk_create('e1242000-0000-0000-0000-000000000001',gen_random_uuid(),'Amended booking guest','','','e1243000-0000-0000-0000-000000000001',current_date+30,current_date+32,1,0,null,null,'','direct',6000)::text,true);
select set_config('test.pricing.version',public.room_pricing_workspace('e1242000-0000-0000-0000-000000000001')->>'version',true);
select public.room_pricing_save('e1242000-0000-0000-0000-000000000001',gen_random_uuid(),current_setting('test.pricing.version')::integer,'e1243000-0000-0000-0000-000000000001',current_date+30,current_date+33,127,6000);
select lives_ok($$select public.frontdesk_update(current_setting('test.pricing.amend')::uuid,(select version from public.reservations where id=current_setting('test.pricing.amend')::uuid),'e1243000-0000-0000-0000-000000000001',current_date+31,current_date+34,1,0,null,null,18000)$$,'An explicit booking amendment can accept new dates and the latest quote');
select is((select total_amount from public.reservations where id=current_setting('test.pricing.amend')::uuid),18000::numeric,'Accepted amendment updates the agreed stay total');
select is((select count(*)::integer from public.reservation_nightly_prices where reservation_id=current_setting('test.pricing.amend')::uuid),3,'Amendment replaces old snapshot nights with the new stay');
select is((select sum(amount)from public.reservation_nightly_prices where reservation_id=current_setting('test.pricing.amend')::uuid),18000::numeric,'Amended nightly prices match the newly accepted total');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1240000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.room_pricing_workspace('e1242000-0000-0000-0000-000000000001')$$,'42501',null,'An unrelated user cannot read the pricing calendar');
select throws_ok($$select public.room_pricing_save('e1242000-0000-0000-0000-000000000001',gen_random_uuid(),0,'e1243000-0000-0000-0000-000000000001',current_date+1,current_date+2,127,5000)$$,'42501',null,'An unrelated user cannot change prices');
reset role;set local role anon;
select throws_ok($$select public.room_pricing_workspace('e1242000-0000-0000-0000-000000000001')$$,'42501',null,'Anonymous users cannot inspect hotel prices');
select *from finish();
rollback;
